def _read_input(self):
    """Read from stdin, or one more files, or directories.
    Yield one line at time.

    - Resolve globs (``foo_*.gz``).
    - Decompress ``.gz`` and ``.bz2`` files.
    - If path is ``-``, read from STDIN.
    - Recursively read all files in a directory
    """
    paths = self.options.args or ['-']

    for path in paths:
        if path == '-':
            for line in self.stdin:
                yield line
        else:
            with open(path, 'rb') as f:
                for line in to_lines(decompress(f, path)):
                    yield line

def _cat_log_lines(fs, path):
    """Yield lines from the given log.

    Log errors rather than raising them.
    """
    try:
        if not fs.exists(path):
            return
        for line in to_lines(fs.cat(path)):
            yield to_unicode(line)
    except (IOError, OSError) as e:
        log.warning("couldn't cat() %s: %r" % (path, e))

def _interpret_spark_logs(fs, matches, partial=True, log_callback=None):
    result = {}
    errors = []

    for match in matches:
        stop_if_partial = False

        path = match['path']
        if log_callback:
            log_callback(path)

        interpretation = _parse_spark_log(_cat_log_lines(fs, path))

        result.update(interpretation)
        # don't _add_implied_job_id() because it doesn't work that way on Spark

        for error in interpretation.get('errors') or ():
            if 'spark_error' in error:
                error['spark_error']['path'] = path
                if error['spark_error']['num_lines'] > 1:
                    stop_if_partial = True
                    # still worth parsing all the errors in this log

            for id_key in 'attempt_id', 'container_id':
                if id_key in match:
                    error[id_key] = match[id_key]
            _add_implied_task_id(error)

            errors.append(error)

        if partial and stop_if_partial:
            result['partial'] = True
            break

    if errors:
        result['errors'] = errors

    return result

def _interpret_emr_step_syslog(fs, matches):
    """Extract information from step syslog (see :py:func:`_parse_step_log()`),
    which may be split into several chunks by timestamp"""
    # going to merge results for each log into final result
    errors = []
    result = {}

    for match in matches:
        path = match['path']

        interpretation = _parse_step_syslog(_cat_log_lines(fs, path))

        result.update(interpretation)
        for error in result.get('errors') or ():
            if 'hadoop_error' in error:
                error['hadoop_error']['path'] = path
            _add_implied_task_id(error)
            errors.append(error)

    _add_implied_job_id(result)
    if errors:
        result['errors'] = errors

    return result
